let CUS=[],CB={},DEVS={},ORD=[],LINES=[],INVMETA={},INVS={};
const LIVE={}; // dữ liệu lưu trong cơ sở dữ liệu của trang: {bộ sưu tập: {id: tài liệu}}
const LV=k=>LIVE[k]||{};

function calc(l){
  const R=RUL();const qn=Math.max(1,Math.round(+l.qty||1));let base=l.fixed!=null?l.fixed:l.price*l.days*qn;
  l.act=0;l.settle='';
  const phys=l.dev&&l.dev!=='eSim'&&l.prod!=='eSIM';
  if(l.fixed==null&&phys&&!l.months&&l.useDays!=null&&l.useDays!==''&&l.days>0){
    const reg=l.days,u=Math.max(0,Math.min(+l.useDays||0,reg));
    if(u*100>=reg*R.minPct){base=l.price*u*qn;l.settle='full'}
    else if(u>0){base=l.price*u*qn;l.act=R.actFee;l.settle='part'}
    else{base=0;l.act=R.actFee*reg;l.settle='none'}
  }
  l.base=base;
  l.disc=(l.fixed!=null||l.settle==='none')?0:Math.round(base*l.dpct/100);
  l.ex=l.fixed!=null?l.fixed:base-l.disc+l.act+l.fee+l.ins+l.comp+(+l.holdFee||0);
  l.vatAmt=Math.round(l.ex*l.vat/100);
  l.total=l.ex+l.vatAmt;
}
function buildInvoices(){
  INVS={};
  Object.keys(INVMETA).forEach(no=>{INVS[no]=Object.assign({no:+no,lines:[],total:0,ex:0},INVMETA[no])});
  LINES.forEach(l=>{if(l.inv&&INVS[l.inv]){const i=INVS[l.inv];i.lines.push(l);i.total+=l.total;i.ex+=l.ex;i.cus=l.cus}});
  Object.values(INVS).forEach(i=>{
    const terms=(CB[i.cus]&&CB[i.cus].terms)||SET().terms||30;
    i.due=addDays(i.date,+terms||30);i.paid=i.recv?i.total:0;i.out=i.total-i.paid;i.over=!i.recv&&i.due<TODAY;
    i.late=i.recv?Math.max(0,dayDiff(i.due,i.recv)):Math.max(0,dayDiff(i.due,TODAY));
    i.age=i.recv?null:(()=>{const d=dayDiff(i.due,TODAY);return d<=0?0:d<=30?1:d<=60?2:3})();
  });
}
function rebuild(){
  PRC=null;
  const dflt={pct:0,pctFrom:'',pctTo:'',pctNote:'',terms:30,pay:'Từng đơn'};
  CUS=clone(BASE_CUS).map(c=>Object.assign({},dflt,{pct:BASE_PCT[c.id]||0,pctNote:BASE_PCT[c.id]?'Theo các đơn trong sheet':''},c,LV('customers')[c.id]||{})).filter(c=>!c.deleted);
  Object.entries(LV('customers')).forEach(([id,c])=>{if(!c.deleted&&!CUS.some(x=>x.id===id))CUS.push(Object.assign({},dflt,c,{id}))});
  CUS.forEach(c=>{if(!c.en&&c.legal)c.en=toEn(c.legal)});
  CB={};CUS.forEach(c=>CB[c.id]=c);
  DEVS=clone(BASE_DEVS);Object.entries(LV('devices')).forEach(([k,v])=>{DEVS[k]=Object.assign(DEVS[k]||{},v)});
  ORD=clone(BASE_ORD);Object.values(LV('orders')).forEach(o=>{const c=clone(o),ix=ORD.findIndex(x=>x.code===c.code);if(c.deleted){if(ix>=0)ORD.splice(ix,1);return}if(ix>=0)ORD[ix]=c;else ORD.push(c)});
  LINES=[];
  ORD.forEach(o=>{
    if(!CB[o.cus])CB[o.cus]={id:o.cus,name:'(khách đã xóa)',legal:'',en:'',mst:'',src:'',contact:'',phone:'',email:'',addr:'',area:'',pay:'',pct:0,terms:30};
    o.lines=o.lines.map(L);
    o.lines.forEach((l,i)=>{
      const op=LV('lineops')[o.code+'__'+i];if(op)Object.assign(l,op);
      if(l.c&&!CTRY[l.c]&&l.prod==='eSIM')CTRY[l.c]=l.c;l.o=o;l.cus=o.cus;l.area=o.area;l.demo=!!o.demo;l.user=l.user||o.user||'';l.idx=i;LINES.push(l);
    });
  });
  LINES.forEach(calc);
  INVMETA=clone(BASE_INV);Object.entries(LV('invoices')).forEach(([k,v])=>{INVMETA[k]=Object.assign(INVMETA[k]||{},v)});
  buildInvoices();
}
const SET=()=>{const s=Object.assign({name:'',addr:'',mst:'',phone:'',email:'',bank:'',acc:'',holder:'',signer:'',title:'Giám đốc',terms:30,staff:[]},RULES0,(LV('settings')).company||{});['bank','acc','holder'].forEach(k=>{s[k+'W']=s[k+'W']||s[k]||'';s[k+'E']=s[k+'E']||s[k]||''});if(!Array.isArray(s.staff))s.staff=[];if(!s.quoteTerms||s.quoteTerms===DEF_TERMS)s.quoteTerms=termsFrom(s);return s};
const signSnap=id=>{const s=SET();const d={id:'',dir:true,name:s.signer||'',title:s.title||'Giám đốc',authNo:'',authDate:''};if(!id)return d;const st=(s.staff||[]).find(x=>x.id===id);return st?{id,dir:false,name:st.name||'',title:st.title||'',authNo:st.authNo||'',authDate:st.authDate||''}:d};
