const AGE=['Chưa đến hạn','Quá 1–30 ngày','Quá 31–60 ngày','Quá trên 60 ngày'];

function lineState(l){
  if(l.st==='pending')return{k:'pending',label:'Chờ giao',tone:'info'};
  if(l.st==='using'){
    if(l.renew)return{k:'using',label:'Đang thuê',tone:'ok',note:'Gia hạn hàng tháng'};
    if(l.hold)return{k:'hold',label:'Khách giữ máy',tone:'info'};
    if(l.e<TODAY)return{k:'overdue',label:'Quá hạn chưa thu',tone:'bad',late:dayDiff(l.e,TODAY)};
    return{k:'using',label:'Đang thuê',tone:'ok'};
  }
  return{k:'closed',label:l.st==='returned'?'Đã trả':'Đã dùng',tone:'mute'};
}
const isPhys=l=>l.dev!=='eSim';
const needsRet=l=>isPhys(l)&&(l.st==='used'||l.st==='returned')&&!l.ret;
function orderState(o){
  const ss=o.lines.map(lineState).map(s=>s.k);
  if(ss.includes('overdue'))return{k:'overdue',label:'Quá hạn',tone:'bad'};
  if(ss.includes('using'))return{k:'using',label:'Đang dùng',tone:'ok'};
  if(ss.includes('hold'))return{k:'hold',label:'Khách giữ máy',tone:'info'};
  if(ss.includes('pending'))return{k:'pending',label:'Chờ giao',tone:'info'};
  return{k:'done',label:'Hoàn tất',tone:'mute'};
}
function payState(o){
  let none=0,over=0,wait=0,paid=0;
  o.lines.forEach(l=>{if(!l.inv||!INVS[l.inv])none++;else{const i=INVS[l.inv];if(i.recv)paid++;else if(i.over)over++;else wait++}});
  if(over)return{k:'overdue',label:'Quá hạn thu',tone:'bad'};
  if(wait)return{k:'wait',label:'Chờ thu',tone:'warn'};
  if(none)return{k:'none',label:'Chưa xuất HĐ',tone:'mute'};
  return{k:'paid',label:'Đã thu',tone:'ok'};
}
const unbilled=o=>o.lines.some(l=>!l.inv);

/* ---- quy định thời gian giao máy: Grab trước 1,5 ngày; CPN trước 3 ngày (HN, HCM, lân cận HN) hoặc 5 ngày (khu vực khác) ---- */
const NEAR_HN=['bac ninh','bac giang','hung yen','hai duong','hai phong','vinh phuc','phu tho','thai nguyen','ha nam','hoa binh','nam dinh','ninh binh','thai binh','quang ninh'];
function zoneOf(addr,area,note){
  const t=nrm((note||'')+' '+(addr||''));
  if(/ha noi|hanoi/.test(t))return 'HN';
  if(/ho chi minh|hcm|sai gon|saigon/.test(t))return 'HCM';
  if(NEAR_HN.some(p=>t.indexOf(p)>=0))return 'NEAR';
  if(area==='HN'||area==='HCM')return area;
  return 'FAR';
}
const ZONE_LBL={HN:'Hà Nội',HCM:'TP.HCM',NEAR:'tỉnh lân cận Hà Nội',FAR:'khu vực khác'};
/* trả về {days,dl,time,rule,zone} hoặc null nếu đơn vị giao không có quy định */
/* lùi n ngày làm việc (T2 đến T6), bỏ qua thứ bảy và chủ nhật */
function subWorkDays(d,n){let x=d;while(n>0){x=addDays(x,-1);const w=new Date(x+'T00:00:00').getDay();if(w!==0&&w!==6)n--}return x}
function leadRule(firm,addr,area,note,start){
  const zone=zoneOf(addr,area,note);let days=0,time='',rule='';
  if(firm==='Grab'){days=1.5;time='12:00';rule='Grab: giao trước 1,5 ngày'}
  else if(firm==='Chuyển phát khác'){days=(zone==='FAR')?5:3;rule='Chuyển phát: hẹn lịch trước '+days+' ngày ('+ZONE_LBL[zone]+')'}
  else return null;
  const back=Math.ceil(days);
  let earliest=TODAY;for(let k=0;k<60;k++){if(subWorkDays(earliest,back)>=TODAY)break;earliest=addDays(earliest,1)}
  return{days,time,rule:rule+', tính ngày làm việc T2–T6',zone,dl:start?subWorkDays(start,back):'',earliest};
}
function lineLead(l){
  if(!isPhys(l)||!l.o)return null;const c=CB[l.cus]||{};
  return leadRule(l.o.firm,c.addr,l.o.area,l.o.areaNote,l.s);
}
