const ESIM_REG={"CNM":"Châu Á","CNHK":"Đa quốc gia","HKMO":"Châu Á","JP":"Châu Á","TH":"Châu Á","SG":"Châu Á","MY":"Châu Á","TSM":"Đa quốc gia","TSM3":"Đa quốc gia","ASEAN5":"Đa quốc gia","ASEAN6":"Đa quốc gia","ASIA13":"Đa quốc gia","VN":"Châu Á","KR":"Châu Á","TW":"Châu Á","US":"Bắc Mỹ","EUTR":"Đa quốc gia","EU":"Châu Âu","ID":"Châu Á","AUNZ":"Đa quốc gia","AU":"Châu Đại Dương","AE":"Châu Á","TR":"Châu Âu","RU":"Châu Âu","IN":"Châu Á"};
Object.entries({"CNM":"Trung Quốc đại lục","CNHK":"Trung Quốc + Hồng Kông + Macao","HKMO":"Hồng Kông + Macao","JP":"Nhật Bản","TH":"Thái Lan","SG":"Singapore","MY":"Malaysia","TSM":"3 nước TH - SG - MY (theo gói)","TSM3":"Pass 3 nước TH - SG - MY","ASEAN5":"ASEAN 5 (TH, SG, MY, ID, VN)","ASEAN6":"ASEAN 6 Pass (TH, SG, MY, ID, VN, PH)","ASIA13":"Châu Á 13 nước (JP, KR, VN, HK, MO, TW, MY, SG, TH, ID, KH, AU, NZ)","VN":"Việt Nam","KR":"Hàn Quốc","TW":"Đài Loan","US":"Mỹ","EUTR":"Châu Âu + Thổ Nhĩ Kỳ","EU":"Châu Âu","ID":"Indonesia","AUNZ":"Úc và New Zealand","AU":"Úc","AE":"UAE (Ả Rập Thống nhất)","TR":"Thổ Nhĩ Kỳ","RU":"Nga","IN":"Ấn Độ"}).forEach(([k,v])=>{if(!(k in CTRY))CTRY[k]=v});
const esimPkg=(t,amt,d,ip)=>(t==='d'?`${amt}/ngày × ${d} ngày`:`${amt} / ${d} ngày`)+(ip?' (không IP Hồng Kông)':'');
const ESIM_BASE=BASE_ESIM.map(r=>{const [c,t,amt,days,src,price,ci,ip,sp,row,v]=r;const pkg=esimPkg(t,amt,days,ip);return {id:'es'+row,name:'eSIM '+(CTRY[c]||c)+' · '+pkg,kind:'eSIM',c,unit:'Gói',pkg,ptype:t,amt,days,v,ip,src,cover:ci>=0?ESIM_COV[ci]:'',fup:sp?'128kbps':'',price,priceVat:Math.round(price*1.1),note:'',region:ESIM_REG[c]||'',active:true}});
const PKG_ORD=k=>{const i=PKGS.indexOf(k);return i<0?9:i};
let PRC=null;
const stdPrices=()=>{if(PRC)return PRC;const m={};BASE_PRICES.concat(ESIM_BASE).forEach(p=>m[p.id]=Object.assign({},p));Object.entries(LV('prices')).forEach(([k,v])=>{m[k]=Object.assign(m[k]||{},v,{id:k})});
  Object.values(m).forEach(p=>{if(!p.region){const r=String(p.note||'').split(' · ')[0];p.region=REGIONS.indexOf(r)>=0?r:''}});
  return PRC=Object.values(m).filter(p=>!p.deleted).sort((a,b)=>{const ka=a.kind+'|'+(CTRY[a.c]||a.c||'')+'|'+PKG_ORD(a.pkg||'')+a.unit,kb=b.kind+'|'+(CTRY[b.c]||b.c||'')+'|'+PKG_ORD(b.pkg||'')+b.unit;return ka.localeCompare(kb,'vi')})};
