const PLNEWC={"GL120":"Toàn cầu 120+","EU40":"Châu Âu (40+ khu vực)","GL139":"Toàn cầu 139+","USCA":"Mỹ + Canada","AUAPI":"Úc (API)","GUSP":"Guam + Saipan","ASIA10":"Châu Á (10 nước)","MV":"Maldives","ASIA7":"Châu Á (7 nước)","EU30":"Châu Âu (30+ khu vực)","NZAPI":"New Zealand (API)","NAMT":"Bắc Mỹ (Mỹ, Canada, Mexico) – top-up được","AFR":"Châu Phi (gói khu vực)","ASIA20":"Châu Á (20 nước)","NAMN":"Bắc Mỹ (Mỹ, Canada, Mexico) – không top-up"};
Object.entries(PLNEWC).forEach(([k,v])=>{if(!(k in CTRY)&&Object.values(PLDATA).some(d=>d.wifi.some(r=>r[0]===k)))CTRY[k]=v});
const PL_DAYS=[1,3,5,7,10,14,15,30];
const PLISTS=[['toyota','Toyota'],['yamaha','Yamaha']];
const plName=id=>(PLISTS.find(x=>x[0]===id)||[0,''])[1];
let PLSCOPE='';const PLC={};
function plBuild(id){
  const D=PLDATA[id],out=[],seen={},reg={};
  BASE_PRICES.concat(ESIM_BASE).forEach(p=>{if(p.c&&!reg[p.c]){const r=p.region||String(p.note||'').split(' · ')[0];if(REGIONS.indexOf(r)>=0)reg[p.c]=r}});
  const rg=c=>reg[c]||(PLNEWC[c]?'Đa quốc gia':'');
  const add=o=>{const k=o.kind+'|'+o.c+'|'+o.pkg;if(seen[k]){seen[k]++;o.pkg+=' · phương án '+seen[k]}else seen[k]=1;
    o.id='pl_'+id+'_'+out.length;o.pl=id;o.active=true;o.region=rg(o.c);o.note='';o.src='';o.cover='';o.priceVat=Math.round(o.price*1.1);out.push(o)};
  D.wifi.forEach(([c,pk,price])=>add({name:'Wi-Fi '+(CTRY[c]||c)+' · '+pk.replace('/day',' mỗi ngày'),kind:'Wifi device',c,unit:'Ngày',pkg:pk,price}));
  /* eSIM: không có giá riêng, dùng bảng giá thường */
  return out.concat(stdPrices().filter(p=>p.kind==='eSIM'));
}
const prices=sc=>{sc=sc===undefined?PLSCOPE:sc;return sc&&PLDATA[sc]?(PLC[sc]||(PLC[sc]=plBuild(sc))):stdPrices()};
const plAuto=c=>{const t=[c&&c.name,c&&c.legal,c&&c.en].join(' ');return /toyota/i.test(t)?'toyota':/yamaha/i.test(t)?'yamaha':''};
const custPL=cid=>{const c=cid&&cid!=='__new'?CB[cid]:null;if(!c)return '';const v=c.plist!=null?c.plist:plAuto(c);return PLDATA[v]&&plAuto(c)===v?v:''};
const priceById=id=>{if(!id)return undefined;const m=/^pl_([a-z]+)_/.exec(id);if(m&&PLDATA[m[1]])return prices(m[1]).find(p=>p.id===id);return stdPrices().find(p=>p.id===id)};
function findPrice(prod,c,unit,pkg){const L=prices().filter(p=>p.active!==false&&p.kind===prod&&p.c===c&&p.unit===unit);if(!pkg)return L[0];return L.find(p=>p.pkg===pkg)||L.find(p=>!p.pkg)}
function pkgOptions(prod,c,cur,unit){if(prod==='eSIM'){const L=prices().filter(p=>p.active!==false&&p.kind==='eSIM'&&p.c===c&&p.pkg);const seen={};const o=[];L.sort((a,b)=>(a.ptype===b.ptype?0:a.ptype==='d'?-1:1)||(String(a.amt).replace(/\D/g,'')*(/GB/.test(a.amt)?1000:1)-String(b.amt).replace(/\D/g,'')*(/GB/.test(b.amt)?1000:1))||((+a.days||0)-(+b.days||0))).forEach(p=>{if(!seen[p.pkg]){seen[p.pkg]=1;o.push(p.pkg)}});if(cur&&o.length&&o.indexOf(cur)<0)o.push(cur);return o}const o=prices().filter(p=>p.active!==false&&p.kind===prod&&p.c===c&&p.pkg&&(!unit||p.unit===unit)).map(p=>p.pkg).filter((v,i,a)=>a.indexOf(v)===i);return o.sort((x,y)=>PKG_ORD(x)-PKG_ORD(y))}
